query BoardSchema($owner: String!, $number: Int!) {
  repositoryOwner(login: $owner) {
    __typename
    login
    ... on User { projectV2(number: $number) { ...board } }
    ... on Organization { projectV2(number: $number) { ...board } }
  }
}

fragment board on ProjectV2 {
  id
  title
  url
  closed
  fields(first: 100) {
    nodes {
      ... on ProjectV2FieldCommon { id name dataType }
      ... on ProjectV2SingleSelectField { options { id name } }
      ... on ProjectV2IterationField {
        configuration {
          iterations { id title startDate duration }
          completedIterations { id title startDate duration }
        }
      }
    }
  }
}

query BoardItems($owner: String!, $number: Int!, $status: String!, $cursor: String) {
  viewer { login }
  repositoryOwner(login: $owner) {
    ... on User { projectV2(number: $number) { ...items } }
    ... on Organization { projectV2(number: $number) { ...items } }
  }
}

fragment items on ProjectV2 {
  field(name: $status) { ... on ProjectV2SingleSelectField { id } }
  items(first: 100, after: $cursor) {
    totalCount
    pageInfo { hasNextPage endCursor }
    nodes {
      status: fieldValueByName(name: $status) {
        ... on ProjectV2ItemFieldSingleSelectValue { name }
      }
      content {
        __typename
        ... on Issue {
          number
          title
          state
          repository { nameWithOwner }
          labels(first: 100) { totalCount nodes { name } }
          assignees(first: 10) { totalCount nodes { login } }
        }
      }
    }
  }
}

